import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, color } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const group = new Group();

  // Color Palette from Spec
  const cInk = new Color('#16161d');
  const cPaper = new Color('#e8ecf2');
  const cAccent = new Color('#ff2a38');
  const cSurface = new Color('#0b0b10');

  // GSAP animation timeline container
  const timelines = [];

  // Card Aspect Ratio: 512x320 -> 1.6 : 1.0
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Material with TSL gradient and loaded ceramic grain texture
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95,
  });

  // TSL Graph: Vertical gradient from surface to ink, accented subtly at the edge
  const uvNode = uv();
  const gradient = uvNode.y; // 0 (bottom) to 1 (top)
  const baseColorNode = mix(color(cSurface), color(cInk), gradient);

  // Subtle top accent line using step
  const topEdge = uvNode.y.step(0.97);
  const finalColorNode = mix(baseColorNode, color(cAccent), topEdge.mul(0.4));

  material.colorNode = finalColorNode;

  // Load the ceramic map if provided
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed loading ceramic grain texture, falling back to clean gradient', err);
  });

  const cardMesh = new Mesh(geometry, material);
  group.add(cardMesh);

  // Text Content Assembly
  // "Pricing 2" at 39px 400 (roughly 0.18 units height relative to our design system constraints)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = textItems[0]?.text ?? 'Pricing 2';

  const textNode = ctx.fontAtlas.createText(textString, {
    fontSize: 0.14,
    color: '#e8ecf2',
    align: 'center'
  });

  // Position text slightly in front of the card to avoid z-fighting
  textNode.position.set(0, 0, 0.02);
  group.add(textNode);

  // Subtle Entrance Animation
  group.position.y += 0.1;
  group.scale.set(0.9, 0.9, 0.9);

  const tl = gsap.timeline({ defaults: { ease: 'power4.out', duration: 1.2 } });
  tl.to(group.position, { y: 1.0 }, 0); // moves to position.y = 1
  tl.to(group.scale, { x: 1, y: 1, z: 1 }, 0);
  timelines.push(tl);

  // Required cleanup interface
  group.userData = {
    cleanup() {
      timelines.forEach(t => t.kill());
      geometry.dispose();
      material.dispose();
    }
  };

  return group;
}
